import {usePluginStore,useWatchEvent} from '@/hooks/plugin';import {drawTechDial,loadTechDialFont,techDialKey} from '@/tech-dial';
export default function(name:string){const plugin=usePluginStore(),ActionID=window.argv[3].plugin.uuid+'.'+name,instances=new Map<string,any>();function stop(context:string){plugin.Unterval(ActionID+context);instances.delete(context);}async function start(context:string){stop(context);const st={canvas:document.createElement('canvas'),ready:false,last:'',busy:false};instances.set(context,st);try{await loadTechDialFont();if(instances.get(context)!==st)return;st.ready=true;draw(context,true);plugin.Interval(ActionID+context,50,()=>draw(context));}catch(e){console.error(JSON.stringify({event:'tech_dial_font_error',error:String(e)}));}}function draw(context:string,force=false){const st=instances.get(context),a=plugin.getAction(context);if(!st?.ready||!a||st.busy)return;const d=new Date(),s=a.settings as any,key=techDialKey(s,d);if(!force&&key===st.last)return;const canvas=drawTechDial(st.canvas,s,d);if(s.transport==='binary'){st.busy=true;canvas.toBlob(async blob=>{try{if(blob&&instances.get(context)===st){a.setImageBlob(await blob.arrayBuffer(),'image/png');st.last=key;}}finally{st.busy=false;}},'image/png');}else try{a.setImage(canvas.toDataURL('image/jpeg',.93));st.last=key;}catch(e){console.error(JSON.stringify({event:'tech_dial_send_error',error:String(e)}));}}useWatchEvent('action',{ActionID,willAppear:({context})=>start(context),willDisappear:({context})=>stop(context),didReceiveSettings:({context})=>draw(context,true)});}
